// These are sanitized requests generated by codex-cli 0.159.3 against a
// loopback receiver. The receiver's responses are fixtures, not Cloud evidence.
func capturedCodexFrames(t *testing.T, scenario string) []gjson.Result {
	t.Helper()
	raw, err := os.ReadFile("testdata/cloud_codex_0_159_3.json")
	require.NoError(t, err)
	tools := gjson.GetBytes(raw, "tools").Raw
	frames := gjson.GetBytes(raw, "scenarios."+scenario+".frames").Array()
	var imageCaptures []byte
	if len(frames) == 0 {
		imageCaptures, err = os.ReadFile("testdata/codex_0_159_3_images.json")
		require.NoError(t, err)
		frames = gjson.GetBytes(imageCaptures, "scenarios."+scenario+".frames").Array()
	}
	require.NotEmpty(t, frames)
	for i := range frames {
		catalog := tools
		// Original-detail captures preserve gpt-5.5's different tool catalog;
		// the image matrix below does not claim Cloud accepts that whole catalog.
		if ref := frames[i].Get("tools_ref").String(); ref != "" && ref != "cloud_codex_0_159_3.json:tools" {
			catalog = gjson.GetBytes(imageCaptures, "catalogs."+ref).Raw
			require.NotEmpty(t, catalog)
		}
		frame, err := sjson.SetRaw(frames[i].Raw, "request.tools", catalog)
		require.NoError(t, err)
		frames[i] = gjson.Parse(frame)
	}
	return frames
}

func capturedCodexSSE(t *testing.T, frame gjson.Result, bps bool) string {
	t.Helper()
	var wire strings.Builder
	for _, event := range frame.Get("events").Array() {
		if bps {
			// BPS produces officejs envelopes. Use the same requested tools and
			// arguments, rather than pretending it emits native function calls.
			if event.Get("type").String() != "response.completed" {
				continue
			}
			var value map[string]any
			require.NoError(t, json.Unmarshal([]byte(event.Raw), &value))
			response := value["response"].(map[string]any)
			response["model"] = "gpt-6-astra"
			for _, raw := range response["output"].([]any) {
				item := raw.(map[string]any)
				if item["type"] != "function_call" {
					continue
				}
				var args any
				require.NoError(t, json.Unmarshal([]byte(item["arguments"].(string)), &args))
				envelope, err := json.Marshal(map[string]any{"name": item["name"], "arguments": args})
				require.NoError(t, err)
				item["name"] = "run_officejs"
				item["arguments"] = map[string]any{"code": string(envelope)}
			}
			raw, err := json.Marshal(value)
			require.NoError(t, err)
			event = gjson.ParseBytes(raw)
		}
		fmt.Fprintf(&wire, "data: %s\n\n", event.Raw)
	}
	return wire.String()
}

// Exercise complete captured tool/image histories through the public Forward
// path and real WS ingress. BPS has an HTTP upstream; WS is an ingress bridge.
func TestCapturedCodexNativeAndBPSHTTPBridges(t *testing.T) {
	for _, protocol := range []string{"native", "bps"} {
		for _, transport := range []string{"json", "sse", "ws", "ws_to_http"} {
			for _, kind := range []string{"tools", "image", "jpeg", "webp", "gif"} {
				t.Run(protocol+"/"+transport+"/"+kind, func(t *testing.T) {
					isWS := strings.HasPrefix(transport, "ws")
					scenario := "http_" + kind
					if isWS {
						scenario = "ws_" + kind
					}
					if transport == "ws_to_http" && kind == "tools" {
						scenario = "ws_to_http"
					}
					frames := capturedCodexFrames(t, scenario)
					if transport == "ws_to_http" && kind != "tools" {
						// Derived transport-switch case: CLI HTTP requests replay full
						// history; do not move a WS-only delta directly into HTTP.
						frames[len(frames)-1] = capturedCodexFrames(t, "http_"+kind)[1]
					}
					up := &httpUpstreamRecorder{}
					svc := openAIClientToolsTestService(up)
					account := nativeWSTestAccount()
					if protocol == "bps" {
						svc = excelBPSGatewayTestService(up)
						account = excelAccount()
						account.Credentials["model_mapping"] = map[string]any{"gpt-5.1": "gpt-6-astra"}
						enableNativeAttachments(svc)
					}
					svc.cfg = passthroughLifecycleConfig()
					account.Extra["openai_oauth_responses_websockets_v2_mode"] = OpenAIWSIngressModeHTTPBridge
					svc.openaiWSResolver = NewOpenAIWSProtocolResolver(svc.cfg)
					svc.cache = &stubGatewayCache{}
					svc.toolCorrector = NewCodexToolCorrector()
					generated, uploads := 0, 0
					var active gjson.Result
					svc.httpUpstream = &codexModelsHTTPUpstreamStub{do: func(req *http.Request, _ string, _ int64, _ int) (*http.Response, error) {
						raw, err := io.ReadAll(req.Body)
						if err != nil {
							return nil, err
						}
						if strings.Contains(req.URL.Path, "attachments") {
							uploads++
							return bpsCompletionResponse(200, fmt.Sprintf(`{"openai_file_id":"file-fixture%d"}`, uploads)), nil
						}
						generated++
						require.Equal(t, protocol == "bps", req.URL.Host == "bps.openai.com")
						if protocol == "native" {
							require.Len(t, gjson.GetBytes(raw, "tools").Array(), 20)
						} else {
							require.Contains(t, string(raw), "run_officejs")
						}
						for _, item := range active.Get("request.input").Array() {
							if item.Get("type").String() == "function_call_output" && item.Get("output").Type == gjson.String {
								require.Contains(t, string(raw), "fixture_exec_", "tool result must survive history reconstruction")
							}
						}
						response := bpsCompletionResponse(200, capturedCodexSSE(t, active, protocol == "bps"))
						response.Header.Set("Content-Type", "text/event-stream")
						return response, nil
					}}
					ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
					defer cancel()
					turns := make(chan bpsWSTestTurn, len(frames))
					var client *coderws.Conn
					var done <-chan error
					lastID := ""
					totalInput, totalOutput := 0, 0
					for i, frame := range frames {
						active = frame
						body := capturedCodexBody(t, frame, transport != "json")
						if frame.Get("request.previous_response_id").Exists() && lastID != "" {
							body, _ = sjson.SetBytes(body, "previous_response_id", lastID)
						}
						var response gjson.Result
						var result *OpenAIForwardResult
						useWS := isWS && !(transport == "ws_to_http" && i == len(frames)-1)
						if useWS {
							if client == nil {
								client, done = startOpenAIWSMemorySession(t, svc, account, nil, string(body), &OpenAIWSIngressHooks{AfterTurn: func(_ int, r *OpenAIForwardResult, e error) { turns <- bpsWSTestTurn{r, e} }})
								defer client.CloseNow()
							} else {
								require.NoError(t, client.Write(ctx, coderws.MessageText, body))
							}
							events := readBPSWSTestTurn(t, client)
							require.Equal(t, "response.completed", gjson.GetBytes(events[len(events)-1], "type").String(), string(events[len(events)-1]))
							response = gjson.GetBytes(events[len(events)-1], "response")
							turn := <-turns
							require.NoError(t, turn.err)
							result = turn.result
						} else {
							body, _ = sjson.DeleteBytes(body, "type")
							rec := httptest.NewRecorder()
							c, _ := gin.CreateTestContext(rec)
							c.Request = httptest.NewRequest("POST", "/v1/responses", strings.NewReader(string(body))).WithContext(ctx)
							var err error
							result, err = svc.Forward(ctx, c, account, body)
							require.NoError(t, err, rec.Body.String())
							response = cloudContractResponse(rec.Body.String())
						}
						lastID = response.Get("id").String()
						require.NotEmpty(t, lastID)
						if frame.Get("request.generate").Exists() {
							require.Equal(t, 0, generated)
							continue
						}
						require.NotNil(t, result)
						totalInput += result.Usage.InputTokens
						totalOutput += result.Usage.OutputTokens
						expected := frame.Get("events").Array()
						terminal := expected[len(expected)-1].Get("response")
						require.Equal(t, len(terminal.Get("output").Array()), len(response.Get("output").Array()))
						require.Equal(t, "gpt-5.1", response.Get("model").String())
						if protocol == "bps" {
							require.Equal(t, "gpt-6-astra", result.UpstreamResponseModel)
						}
						for j, item := range terminal.Get("output").Array() {
							if item.Get("type").String() == "function_call" {
								actual := response.Get(fmt.Sprintf("output.%d", j))
								require.Equal(t, item.Get("name").String(), actual.Get("name").String())
								require.JSONEq(t, item.Get("arguments").String(), actual.Get("arguments").String())
							}
						}
					}
					if client != nil {
						requireBPSWSTestServerExit(t, client, done)
					}
					require.Equal(t, 2, generated, "no replay or correction attempt on valid client tools")
					require.Equal(t, 20, totalInput)
					require.Equal(t, 4, totalOutput)
					if protocol == "bps" && kind != "tools" {
						require.Positive(t, uploads)
					}
				})
			}
		}
	}
}

func capturedCodexBody(t *testing.T, frame gjson.Result, stream bool) []byte {
	t.Helper()
	body, err := sjson.Set(frame.Get("request").Raw, "stream", stream)
	require.NoError(t, err)
	return []byte(body)
}

func TestCloudCapturedCodexSequenceParsing(t *testing.T) {
	for _, scenario := range []string{"http_tools", "ws_tools", "http_image", "ws_image", "http_jpeg", "ws_jpeg", "http_webp", "ws_webp", "http_gif", "ws_gif", "http_svg", "ws_svg", "ws_to_http", "http_429", "ws_partial_error", "http_cancel", "ws_cancel"} {
		for i, frame := range capturedCodexFrames(t, scenario) {
			t.Run(fmt.Sprintf("%s/%d", scenario, i), func(t *testing.T) {
				if frame.Get("request.generate").Exists() {
					return
				} // ingress owns local warmup
				body, err := sjson.DeleteBytes(capturedCodexBody(t, frame, true), "type")
				require.NoError(t, err)
				p, err := parseCloudProtocolRequest(body)
				require.NoError(t, err)
				require.Len(t, p.toolNames, 106)
				if strings.HasSuffix(scenario, "_svg") {
					// Successful text transport is not successful SVG vision:
					// this CLI rejected SVG locally before sending image bytes.
					require.NotContains(t, frame.Get("request.input").Raw, `"type":"input_image"`)
					if output := frame.Get(`request.input.#(type=="function_call_output").output`); output.Exists() {
						require.Equal(t, "unable to process image: invalid or unsupported image data", output.String())
					}
				}
				for _, input := range p.input {
					part := input.(map[string]any)
					if part["type"] == "image" {
						require.Equal(t, "high", part["detail"])
					}
				}
				for _, item := range frame.Get("request.input").Array() {
					if item.Get("type").String() != "function_call_output" {
						continue
					}
					encoded, err := json.Marshal(p.outputHistory[item.Get("call_id").String()])
					require.NoError(t, err)
					require.JSONEq(t, item.Get("output").Raw, string(encoded))
				}
			})
		}
	}
}

func TestCloudCapturedCodexImageContinuation(t *testing.T) {
	for _, kind := range []string{"image", "jpeg", "webp", "gif"} {
		for _, transports := range [][2]string{{"sse", "sse"}, {"json", "json"}, {"ws", "ws"}, {"ws", "sse"}, {"sse", "ws"}, {"ws", "json"}, {"json", "ws"}} {
			t.Run(kind+"/"+transports[0]+"_to_"+transports[1], func(t *testing.T) {
				// HTTP captures retain complete history and the exact requested
				// view_image path. The WS captures may send an incremental tool reply.
				httpFrames := capturedCodexFrames(t, "http_"+kind)
				toolCall := httpFrames[0].Get(`events.#(type=="response.completed").response.output.0`)
				require.Equal(t, "function_call", toolCall.Get("type").String())
				var toolArguments map[string]any
				require.NoError(t, json.Unmarshal([]byte(toolCall.Get("arguments").String()), &toolArguments))
				imageURL := httpFrames[1].Get(`request.input.#(type=="function_call_output").output.0.image_url`).String()
				require.NotEmpty(t, imageURL)
				svc, in, store, wire := cloudForwardFixture(t, nil)
				in.Account.Credentials["model_mapping"] = map[string]any{"gpt-5.1": "gpt-5.1"}
				ctx, cancel := context.WithTimeout(t.Context(), 8*time.Second)
				defer cancel()
				done := make(chan struct{})
				defer func() { cancel(); <-done }()
				go func() {
					defer close(done)
					cloudWireResponse(t, ctx, wire, "initialize", map[string]any{})
					require.Equal(t, "initialized", cloudTestMessage(t, ctx, wire).Method)
					start := cloudTestMessage(t, ctx, wire)
					require.Equal(t, "thread/start", start.Method)
					require.Len(t, gjson.GetBytes(start.Params, "dynamicTools.0.tools").Array(), 106)
					cloudTestRead(wire, map[string]any{"id": start.ID, "result": map[string]any{"model": "gpt-5.1", "thread": map[string]any{"id": "thread"}}})
					cloudWireResponse(t, ctx, wire, "thread/inject_items", map[string]any{})
					turn := cloudTestMessage(t, ctx, wire)
					require.Equal(t, "turn/start", turn.Method)
					require.Equal(t, "high", gjson.GetBytes(turn.Params, `input.#(type=="image").detail`).String())
					require.Equal(t, imageURL, gjson.GetBytes(turn.Params, `input.#(type=="image").url`).String(), "captured user and tool images retain the same bytes and format")
					cloudTestRead(wire, map[string]any{"id": turn.ID, "result": map[string]any{"turn": map[string]any{"id": "turn"}}})
					cloudTestRead(wire, map[string]any{"id": "image-rpc", "method": "item/tool/call", "params": map[string]any{"threadId": "thread", "turnId": "turn", "callId": "image-call", "namespace": cloudClientToolNamespace, "tool": "view_image", "arguments": toolArguments}})
					var raw []byte
					select {
					case raw = <-wire.writes:
					case <-ctx.Done():
						t.Error(ctx.Err())
						return
					}
					require.Equal(t, "image-rpc", gjson.GetBytes(raw, "id").String())
					require.Contains(t, string(raw), `"type":"inputImage"`)
					require.Contains(t, string(raw), imageURL, "tool image format and bytes must reach the Cloud RPC")
					cloudWireComplete(wire)
				}()
				lastID, callID := "", ""
				for index, transport := range transports {
					scenario := "http_" + kind
					if transport == "ws" {
						scenario = "ws_" + kind
					}
					frames := capturedCodexFrames(t, scenario)
					frame := frames[len(frames)-2+index]
					body := capturedCodexBody(t, frame, transport != "json")
					if index == 0 && frame.Get("request.previous_response_id").Exists() {
						// The real WS owner consumes only its own local warmup ID
						// before invoking this bridge. Preserve that boundary here.
						require.False(t, frames[0].Get("request.generate").Bool())
						require.True(t, frames[0].Get("request.generate").Exists())
						require.Equal(t, frames[0].Get(`events.#(type=="response.completed").response.id`).String(), frame.Get("request.previous_response_id").String())
						body, _ = sjson.DeleteBytes(body, "previous_response_id")
					}
					if index == 1 {
						for i, item := range frame.Get("request.input").Array() {
							if item.Get("type").String() == "function_call" || item.Get("type").String() == "function_call_output" {
								require.Equal(t, toolCall.Get("call_id").String(), item.Get("call_id").String())
								var rewriteErr error
								body, rewriteErr = sjson.SetBytes(body, fmt.Sprintf("input.%d.call_id", i), callID)
								require.NoError(t, rewriteErr)
							}
						}
						if frame.Get("request.previous_response_id").Exists() {
							body, _ = sjson.SetBytes(body, "previous_response_id", lastID)
						}
					}
					requestCtx, c, rec := cloudContractContext(t, svc, in, ctx, body)
					var result *OpenAIForwardResult
					var err error
					if transport == "ws" {
						result, err = svc.proxyOpenAIWSHTTPBridgeTurn(requestCtx, c, in.Account, "unused", body, len(body), "gpt-5.1", "", "", "", "", index+1, func(event []byte) error { _, e := fmt.Fprintf(rec, "data: %s\n\n", event); return e })
					} else {
						result, err = svc.Forward(requestCtx, c, in.Account, body)
					}
					require.NoError(t, err, rec.Body.String())
					require.NotNil(t, result)
					response := cloudContractResponse(rec.Body.String())
					require.Equal(t, "completed", response.Get("status").String(), rec.Body.String())
					lastID = response.Get("id").String()
					if index == 0 {
						callID = response.Get("output.0.call_id").String()
						require.NotEmpty(t, callID)
						require.Equal(t, "view_image", response.Get("output.0.name").String())
						require.Equal(t, gjson.Null, response.Get("usage").Type)
						require.Zero(t, store.settlementCount(), "handoff is not a final bill")
					} else {
						require.Equal(t, "ok", response.Get("output.0.content.0.text").String())
						require.Equal(t, int64(10), response.Get("usage.input_tokens").Int())
						require.Equal(t, 1, store.settlementCount(), "one Cloud model turn across both client requests")
					}
				}
			})
		}
	}
}

// Native OAuth's WS upstream is a separate path from the HTTP bridge. Keep
// actual CLI warmup, full-history tool outputs and incremental image outputs.
func TestCapturedCodexNativeWSUpstream(t *testing.T) {
	for _, mode := range []string{OpenAIWSIngressModeCtxPool, OpenAIWSIngressModePassthrough} {
		for _, kind := range []string{"tools", "image", "jpeg", "webp", "gif"} {
			t.Run(mode+"/"+kind, func(t *testing.T) {
				frames := capturedCodexFrames(t, "ws_"+kind)
				cfg := passthroughLifecycleConfig()
				cfg.Gateway.OpenAIWS.OAuthEnabled = true
				up := newStagedPassthroughConn()
				up.frames = make(chan stagedPassthroughFrame, 32)
				svc := newPassthroughLifecycleService(cfg, up)
				pool := newOpenAIWSConnPool(cfg)
				pool.setClientDialerForTest(&stagedPassthroughDialer{conn: &nativeCodexStagedConn{up}})
				svc.openaiWSPool = pool
				t.Cleanup(pool.Close)
				account := nativeWSTestAccount()
				account.Extra["openai_oauth_responses_websockets_v2_mode"] = mode
				turns := make(chan bpsWSTestTurn, 3)
				client, done := startOpenAIWSMemorySession(t, svc, account, nil, string(capturedCodexBody(t, frames[0], true)), &OpenAIWSIngressHooks{AfterTurn: func(_ int, r *OpenAIForwardResult, e error) { turns <- bpsWSTestTurn{r, e} }})
				defer client.CloseNow()
				ctx, cancel := context.WithTimeout(t.Context(), 8*time.Second)
				defer cancel()
				lastID := ""
				total := 0
				for index, frame := range frames {
					if index > 0 {
						body := capturedCodexBody(t, frame, true)
						if frame.Get("request.previous_response_id").Exists() {
							body, _ = sjson.SetBytes(body, "previous_response_id", lastID)
						}
						require.NoError(t, client.Write(ctx, coderws.MessageText, body))
					}
					wire := requirePassthroughUpstreamWrite(t, up, 3*time.Second)
					require.Len(t, gjson.GetBytes(wire, "tools").Array(), 20)
					require.Equal(t, "response.create", gjson.GetBytes(wire, "type").String())
					if index == 2 {
						require.Contains(t, string(wire), "function_call_output")
					}
					for _, event := range frame.Get("events").Array() {
						up.Send(event.Raw)
					}
					events := readNativeWSTestTurn(t, client)
					terminal := events[len(events)-1]
					require.Equal(t, "response.completed", gjson.GetBytes(terminal, "type").String())
					lastID = gjson.GetBytes(terminal, "response.id").String()
					turn := <-turns
					require.NoError(t, turn.err)
					if turn.result != nil {
						total += turn.result.Usage.InputTokens
					}
				}
				require.Equal(t, 20, total)
				requireNativeWSTestServerExit(t, client, done)
			})
		}
	}
}

func TestCapturedCodexNativeHTTPToWS(t *testing.T) {
	for _, stream := range []bool{false, true} {
		for _, kind := range []string{"tools", "image", "jpeg", "webp", "gif"} {
			t.Run(fmt.Sprintf("stream=%t/%s", stream, kind), func(t *testing.T) {
				cfg := passthroughLifecycleConfig()
				cfg.Gateway.OpenAIWS.OAuthEnabled = true
				up := newStagedPassthroughConn()
				up.frames = make(chan stagedPassthroughFrame, 32)
				svc := newPassthroughLifecycleService(cfg, up)
				pool := newOpenAIWSConnPool(cfg)
				pool.setClientDialerForTest(&stagedPassthroughDialer{conn: &nativeCodexStagedConn{up}})
				svc.openaiWSPool = pool
				t.Cleanup(pool.Close)
				account := nativeWSTestAccount()
				delete(account.Extra, "openai_passthrough")
				account.Extra["openai_oauth_responses_websockets_v2_mode"] = OpenAIWSIngressModeCtxPool
				account.Extra["responses_websockets_v2_enabled"] = true
				ctx, cancel := context.WithTimeout(t.Context(), 8*time.Second)
				defer cancel()
				for _, frame := range capturedCodexFrames(t, "http_"+kind) {
					body := capturedCodexBody(t, frame, stream)
					rec := httptest.NewRecorder()
					c, _ := gin.CreateTestContext(rec)
					c.Request = httptest.NewRequest("POST", "/v1/responses", strings.NewReader(string(body))).WithContext(ctx)
					done := make(chan bpsWSTestTurn, 1)
					go func() { r, e := svc.Forward(ctx, c, account, body); done <- bpsWSTestTurn{r, e} }()
					wire := requirePassthroughUpstreamWrite(t, up, 3*time.Second)
					require.Len(t, gjson.GetBytes(wire, "tools").Array(), 20)
					for _, event := range frame.Get("events").Array() {
						up.Send(event.Raw)
					}
					var turn bpsWSTestTurn
					select {
					case turn = <-done:
					case <-ctx.Done():
						t.Fatal(ctx.Err())
					}
					require.NoError(t, turn.err)
					require.NotNil(t, turn.result)
					require.True(t, turn.result.OpenAIWSMode)
					require.Equal(t, 10, turn.result.Usage.InputTokens)
					require.Equal(t, 2, turn.result.Usage.OutputTokens)
					require.Equal(t, "completed", cloudContractResponse(rec.Body.String()).Get("status").String())
				}
				require.Empty(t, svc.httpUpstream.(*httpUpstreamRecorder).requests, "HTTP ingress must actually use the WS upstream")
			})
		}
	}
}

func TestCapturedCodexHTTPFailuresAndWSBridges(t *testing.T) {
	for _, protocol := range []string{"native", "bps"} {
		for _, transport := range []string{"json", "sse", "ws"} {
			for _, partial := range []bool{false, true} {
				if partial && transport == "json" {
					continue
				} // no downstream partial output for buffered JSON
				t.Run(fmt.Sprintf("%s/%s/partial=%t", protocol, transport, partial), func(t *testing.T) {
					frame := capturedCodexFrames(t, "http_429")[0]
					status := 429
					wire := `{"error":{"type":"rate_limit_error","code":"rate_limit_exceeded","message":"fixture quota"}}`
					if partial {
						frame = capturedCodexFrames(t, "ws_partial_error")[2]
						status = 200
						wire = capturedCodexSSE(t, frame, false)
					}
					up := &httpUpstreamRecorder{resp: bpsCompletionResponse(status, wire)}
					up.resp.Header.Set("Content-Type", "text/event-stream")
					svc := openAIClientToolsTestService(up)
					account := nativeWSTestAccount()
					if protocol == "bps" {
						svc = excelBPSGatewayTestService(up)
						account = excelAccount()
						account.Credentials["model_mapping"] = map[string]any{"gpt-5.1": "gpt-6-astra"}
					}
					body := capturedCodexBody(t, frame, transport != "json")
					ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
					defer cancel()
					rec := httptest.NewRecorder()
					c, _ := gin.CreateTestContext(rec)
					c.Request = httptest.NewRequest("POST", "/v1/responses", strings.NewReader(string(body))).WithContext(ctx)
					var err error
					var result *OpenAIForwardResult
					if transport == "ws" {
						body, _ = sjson.SetBytes(body, "type", "response.create")
						result, err = svc.proxyOpenAIWSHTTPBridgeTurn(ctx, c, account, "test-token", body, len(body), "gpt-5.1", "", "", "", "", 1, func(event []byte) error { _, e := fmt.Fprintf(rec, "data: %s\n\n", event); return e })
					} else {
						result, err = svc.Forward(ctx, c, account, body)
					}
					require.Len(t, up.requests, 1, "no internal replay")
					var failover *UpstreamFailoverError
					if partial {
						require.False(t, errors.As(err, &failover), "visible partial output cannot fail over")
						require.NotNil(t, result)
						require.Equal(t, 10, result.Usage.InputTokens)
						require.Contains(t, rec.Body.String(), "fixture partial")
						require.Contains(t, rec.Body.String(), "response.failed")
						require.Contains(t, rec.Body.String(), "rate_limit_exceeded")
					} else {
						require.ErrorAs(t, err, &failover)
						require.Equal(t, 429, failover.StatusCode)
						require.Empty(t, rec.Body.String(), "recovery belongs to the outer scheduler before response commit")
					}
				})
			}
		}
	}
}

func cloudCapturedWireStart(t *testing.T, ctx context.Context, wire *cloudRPCFakeConn) {
	t.Helper()
	cloudWireResponse(t, ctx, wire, "initialize", map[string]any{})
	require.Equal(t, "initialized", cloudTestMessage(t, ctx, wire).Method)
	cloudWireResponse(t, ctx, wire, "thread/start", map[string]any{"model": "gpt-5.1", "thread": map[string]any{"id": "thread"}})
	cloudWireResponse(t, ctx, wire, "thread/inject_items", map[string]any{})
	cloudWireResponse(t, ctx, wire, "turn/start", map[string]any{"turn": map[string]any{"id": "turn"}})
}
